const data = $json.body ?? $json;

const text = String(
  data.text ?? data.message ?? data.raw_text ?? ""
);

const lines = text.split("\n").map(line => line.trim()).filter(Boolean);
const buttons = Array.isArray(data.buttons) ? data.buttons : [];

const platformAliases = {
  mostaql: "mostaql",
  "مستقل": "mostaql",
  nafezly: "nafezly",
  "نفذلي": "nafezly",
  kafiil: "kafiil",
  "كفيل": "kafiil",
};

const allowedHosts = {
  mostaql: ["mostaql.com", "www.mostaql.com"],
  nafezly: ["nafezly.com", "www.nafezly.com"],
  kafiil: ["kafiil.com", "www.kafiil.com"],
};

const TRACKING_HOST = "url-shortne.tail3d0151.ts.net";

// 1. Read the explicit platform first.
const rawPlatform = String(data.platform ?? "")
  .trim()
  .toLowerCase();

let platform = platformAliases[rawPlatform] ?? rawPlatform;

// 2. If missing or unsupported, infer it from the notification text.
const platformText = `${text}\n${String(data.description ?? "")}`;

if (!allowedHosts[platform]) {
  if (/\bnafezly\b|نفذلي/i.test(platformText)) {
    platform = "nafezly";
  } else if (/\bmostaql\b|مستقل/i.test(platformText)) {
    platform = "mostaql";
  } else if (/\bkafiil\b|كفيل/i.test(platformText)) {
    platform = "kafiil";
  }
}

// 3. Extract the job button URL first, then fall back to other fields.
const jobButton = buttons.find(button =>
  /view job|عرض الوظيفة|عرض المشروع|view project/i.test(
    String(button?.text ?? "")
  ) && typeof button?.url === "string"
);

const candidateUrl =
  jobButton?.url ??
  buttons.find(button => typeof button?.url === "string")?.url ??
  data.url ??
  data.original_tracking_url ??
  data.resolved_url ??
  null;

let jobUrl = null;
let urlType = "invalid";

if (typeof candidateUrl === "string" && allowedHosts[platform]) {
  const candidate = candidateUrl.trim();

  // Accept only HTTPS URLs on the exact tracking hostname.
  const trackingMatch = candidate.match(
    /^https:\/\/url-shortne\.tail3d0151\.ts\.net\/[^/?#]+(?:\?[^#]*)?(?:#.*)?$/i
  );

  if (trackingMatch) {
    jobUrl = candidate;
    urlType = "tracking";
  } else {
    // Validate direct platform URLs.
    // NOTE: the Code node sandbox has no URL constructor (new URL throws
    // ReferenceError), so the URL is validated with a regex instead.
    const match = candidate.match(/^https:\/\/([^/?#]+)(?:[/?#]|$)/i);
    const authority = match?.[1] ?? "";
    const hostname = authority.replace(/:\d+$/, "").toLowerCase();
    const port = authority.match(/:(\d+)$/)?.[1];

    if (
      match &&
      !authority.includes("@") &&
      (!port || port === "443") &&
      allowedHosts[platform].includes(hostname)
    ) {
      jobUrl = candidate;
      urlType = "platform";
    }
  }
}

// 4. Extract title and description without losing the raw notification.
const title =
  data.title ??
  lines.find(line => !/^platform\s*:/i.test(line)) ??
  "Untitled job";

const description = data.description ?? text;

return {
  json: {
    source: data.source ?? "Loki",
    platform: allowedHosts[platform] ? platform : "unknown",
    title,
    description,
    budget: data.budget ?? null,

    url: jobUrl,
    original_tracking_url: urlType === "tracking" ? jobUrl : null,
    resolved_url: urlType === "platform" ? jobUrl : null,

    url_type: urlType,
    ready_for_inspection: Boolean(jobUrl),
    requires_resolution: urlType === "tracking",

    raw_text: text,
    buttons,
    telegram_chat_id: data.telegram_chat_id ?? null,
    telegram_message_id: data.telegram_message_id ?? null,
    received_at: new Date().toISOString(),
  },
};

// Parse the AI Agent's JSON string and preserve the original job context.

const aiRaw = $node["AI Agent"].json.output;

let ai;
try {
  ai = typeof aiRaw === "string" ? JSON.parse(aiRaw) : aiRaw;
} catch (error) {
  return [{
    json: {
      status: "review_required",
      submitted: false,
      reason: "AI output was not valid JSON: " + error.message,
    }
  }];
}

// Recover project context from the earlier workflow nodes.
const parsedJob = $node["Parse Loki Notification"].json;

// "Resolve Tracking URL" and "Trim Job Context" only run on their own branches,
// so read them defensively instead of throwing "node has not been executed".
const readUpstream = (name) => {
  try {
    const node = $(name);
    return node.isExecuted ? (node.first().json ?? {}) : {};
  } catch {
    return {};
  }
};

const resolvedJob = readUpstream("Resolve Tracking URL");
const trimmedJob = readUpstream("Trim Job Context");

// Find platform and URL from the available earlier data.
const platform =
  parsedJob.platform ??
  resolvedJob.platform ??
  null;

const url =
  resolvedJob.final_url ??
  resolvedJob.url ??
  trimmedJob.final_url ??
  parsedJob.url ??
  parsedJob.project_url ??
  null;

const proposal = ai.proposal;
const cost = Number(ai.cost);
const periodDays = Number(ai.period_days);

const valid =
  typeof proposal === "string" &&
  proposal.trim().length > 0 &&
  Number.isFinite(cost) &&
  Number.isInteger(periodDays) &&
  periodDays > 0 &&
  cost > 0 &&
  ["mostaql", "nafezly"].includes(String(platform).toLowerCase()) &&
  typeof url === "string" &&
  url.startsWith("https://");

if (!valid) {
  return [{
    json: {
      status: "review_required",
      submitted: false,
      reason: "Missing or invalid required fields after parsing AI output.",
      missing: {
        proposal: !(typeof proposal === "string" && proposal.trim()),
        cost: !(Number.isFinite(cost) && cost > 0),
        period_days: !(Number.isInteger(periodDays) && periodDays > 0),
        platform: !["mostaql", "nafezly"].includes(String(platform).toLowerCase()),
        url: !(typeof url === "string" && url.startsWith("https://")),
      },
      platform,
      url,
    }
  }];
}

return [{
  json: {
    status: ["eligible", "ready"].includes(ai.status)
  ? "eligible"
  : "review_required",
    submitted: false,
    reason: ai.reason || "",
    platform: String(platform).toLowerCase(),
    url,
    proposal: proposal.trim(),
    cost,
    period_days: periodDays,
    project_title:
      trimmedJob.title ?? parsedJob.title ?? parsedJob.project_title ?? resolvedJob.project_title ?? "",
  }
}];

const j = $json;

const pageText = String(j.page_text ?? '');
const title = String(j.title_from_loki ?? j.page_title ?? '');
const description = String(j.description_from_loki ?? '');

// Normalize Arabic-Indic digits into standard digits.
const normalizeDigits = (value) =>
  String(value)
    .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
    .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));

const lines = normalizeDigits(pageText)
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

// Find the budget label and its nearby value.
const budgetLabel = /^(الميزانية|ميزانية المشروع|budget|project budget)\s*[:：]?$/i;

let budgetText = null;
let budgetLineIndex = -1;

for (let i = 0; i < lines.length; i++) {
  if (budgetLabel.test(lines[i])) {
    budgetLineIndex = i;

    // Usually the value is on the next line.
    budgetText = lines[i + 1] ?? null;

    // If the label and value share a line, capture the value.
    if (!budgetText && /[:：]/.test(lines[i])) {
      budgetText = lines[i].split(/[:：]/).slice(1).join(':').trim() || null;
    }

    break;
  }
}

// Parse the numeric range only when the value clearly contains one.
let budgetMin = null;
let budgetMax = null;
let budgetType = 'unspecified';

if (budgetText) {
  const value = budgetText.replace(/,/g, '');
  const numbers = value.match(/\d+(?:\.\d+)?/g) || [];

  if (numbers.length >= 2 && /[-–—]/.test(value)) {
    budgetMin = Number(numbers[0]);
    budgetMax = Number(numbers[1]);
    budgetType = 'range';
  } else if (numbers.length === 1) {
    const n = Number(numbers[0]);

    if (/[<>≤≥]|(?:up to|maximum|max\.?|حتى|بحد أقصى)/i.test(value)) {
      budgetMax = n;
      budgetType = 'maximum';
    } else {
      budgetMin = n;
      budgetMax = n;
      budgetType = 'fixed';
    }
  }
}

// Keep the budget section in the context even if it appears late on the page.
const budgetContext = budgetLineIndex >= 0
  ? lines.slice(budgetLineIndex, budgetLineIndex + 3).join('\n')
  : 'Budget not found in inspected page text.';

const compact = {
  platform: j.platform,
  title,
  description,
  page_title: j.page_title,
  final_url: j.final_url,

  budget_text: budgetText,
  budget_min: budgetMin,
  budget_max: budgetMax,
  budget_type: budgetType,
  budget_context: budgetContext,

  page_text: pageText.slice(0, 5000),
};

return { json: compact };

const j = $json;

const rawUrl = String(j.url ?? '').trim();

// The Code node sandbox has no URL constructor (new URL throws
// ReferenceError), so the URL is parsed with a regex instead.
const authorityMatch = rawUrl.match(/^https:\/\/([^/?#]+)(?:[/?#]|$)/i);
const authority = authorityMatch?.[1] ?? '';
const host = authority.replace(/:\d+$/, '').toLowerCase();
const port = authority.match(/:(\d+)$/)?.[1];

if (
  !authorityMatch ||
  !host ||
  authority.includes('@') ||
  (port && port !== '443')
) {
  return {
    json: {
      ...j,
      url_type: 'invalid',
      ready_for_inspection: false,
      requires_resolution: false,
      routing_error: 'Invalid or missing URL',
    },
  };
}

// Accept only HTTPS URLs on the supported project platforms.
const isMostaql =
  host === 'mostaql.com' || host.endsWith('.mostaql.com');

const isNafezly =
  host === 'nafezly.com' || host.endsWith('.nafezly.com');

if (isMostaql || isNafezly) {
  const platform = isMostaql ? 'mostaql' : 'nafezly';

  // The direct URL is already the project URL.
  return {
    json: {
      ...j,
      platform,
      url: rawUrl,
      original_tracking_url: rawUrl,
      resolved_url: rawUrl,
      url_type: 'direct',
      requires_resolution: false,
      ready_for_inspection: true,
    },
  };
}

// Only explicitly recognized tracking links should reach the resolver.
// Add other legitimate shortener hosts here if Loki uses them.
const knownTrackingHosts = new Set([
  'url-shortne.tail3d0151.ts.net',
]);

if (knownTrackingHosts.has(host)) {
  return {
    json: {
      ...j,
      original_tracking_url: rawUrl,
      url_type: 'tracking',
      requires_resolution: true,
      ready_for_inspection: true,
    },
  };
}

return {
  json: {
    ...j,
    url_type: 'unknown',
    requires_resolution: false,
    ready_for_inspection: false,
    routing_error: `Unrecognized URL host: ${host}`,
  },
};

